INSERT INTO "MD_SERVER_OPERATION_LOGS" ("ID", "BASE_ID", "BASE_VERSION", "OP_TIME", "AUTHOR", "OPERATIONS") VALUES (6236,'d97049cb-0b8d-4335-876d-7157efb2242e',12,1786328619,'seafevents','[{\"type\":\"update_rows\",\"table_id\":\"0001\",\"rows\":[{\"_ai_summary\":\"本文档介绍了 Seafile 的个人设置与管理：包括查看通知、查看存储空间与共享流量、进入设置修改个人信息/密码/语言、选择默认资料库与注销，以及通过“已连接的设备”管理并删除已连接设备。\",\"_ai_summary_mtime\":\"2026-08-10T02:23:20.946759+00:00\",\"_id\":\"2EGwsvv7Q0KEfQGc-RMHVw\",\"_last_modifier\":\"seafevents\",\"_mtime\":\"2026-08-10T10:23:39+08:00\"},{\"_ai_summary\":\"本文介绍了Seafile的文件历史与回收站功能：文件修改会自动生成版本，可通过“历史”查看、下载、还原并比较文本内容；已删除文件可在“回收站”中还原。文中也说明可通过历史保留期设置版本与删除内容的保存时间。\",\"_ai_summary_mtime\":\"2026-08-10T02:23:20.946759+00:00\",\"_id\":\"8a1WlA1sS_GfGh6yfzvR8A\",\"_last_modifier\":\"seafevents\",\"_mtime\":\"2026-08-10T10:23:39+08:00\"},{\"_ai_summary\":\"本文介绍 Apache HTTP Server 的用途、基本目录/配置结构及常用端口、DocumentRoot等配置要点，覆盖启动重载、日志关注、虚拟主机、HTTPS、反向代理与安全性能建议。并提供 403/404/502/504 等故障排查思路，最后索要系统与目标等信息以便定制可直接部署的配置示例。\",\"_ai_summary_mtime\":\"2026-08-10T02:23:20.946759+00:00\",\"_id\":\"Gyq0Pya0TDmt3pI99GR5ZQ\",\"_last_modifier\":\"seafevents\",\"_mtime\":\"2026-08-10T10:23:39+08:00\"},{\"_ai_summary\":\"本文介绍 MySQL 的分层架构与插件式存储引擎机制，重点对 InnoDB 与 MyISAM、B+ 树索引、MVCC 与 ACID 事务并发控制进行说明。并概述其在 Web、电商金融、高并发分库分表及游戏/日志系统中的应用价值。\",\"_ai_summary_mtime\":\"2026-08-10T02:23:20.946759+00:00\",\"_id\":\"H47fPWq0RjufCJ75408ckg\",\"_last_modifier\":\"seafevents\",\"_mtime\":\"2026-08-10T10:23:39+08:00\"},{\"_ai_summary\":\"本文介绍 Seafile 如何用“资料库”作为顶级容器管理文件：每个资料库具备独立修改历史、可按需同步到桌面，并支持在私人间/群组中共享。文中还讲述新建与加密、共享/权限等操作，以及通过历史与快照实现“时光机”式回滚，并可配置历史保留期限。\",\"_ai_summary_mtime\":\"2026-08-10T02:23:20.946759+00:00\",\"_id\":\"SxkdfcRISM-3giOpVn35CA\",\"_last_modifier\":\"seafevents\",\"_mtime\":\"2026-08-10T10:23:39+08:00\"},{\"_ai_summary\":\"本文介绍Seafile的共享协作功能：支持将资料库/文件夹共享给用户或群组，并可对共享内容及子目录设置精细权限；包含文件锁定以避免冲突编辑。文档还讲解共享管理与外链共享（下载/上传链接），以及链接的密码、过期与预览控制。\",\"_ai_summary_mtime\":\"2026-08-10T02:23:20.946759+00:00\",\"_id\":\"_SYoaFVeRZGLqGNnDOnvjQ\",\"_last_modifier\":\"seafevents\",\"_mtime\":\"2026-08-10T10:23:39+08:00\"},{\"_ai_summary\":\"本文档介绍Seafile 6.3.0新增的“组织架构”功能，用于按部门分级管理资料库，并区分系统管理员、部门管理员与普通成员的权限。内容涵盖部门创建/导入（含AD同步）、成员管理、配额设置、部门资料库的创建/删除/重命名及权限与共享规则。\",\"_ai_summary_mtime\":\"2026-08-10T02:23:20.946759+00:00\",\"_id\":\"jYbqbUlcTPSXJsdOfsngcg\",\"_last_modifier\":\"seafevents\",\"_mtime\":\"2026-08-10T10:23:39+08:00\"},{\"_ai_summary\":\"This document介绍了Seafile文件管理功能，包括目录内上传新建共享、对单个或批量文件/目录进行移动复制删除下载。还涵盖在线预览与在线编辑（部分文件类型需第三方集成）、企业版全文检索、收藏夹与文件活动历史追踪。\",\"_ai_summary_mtime\":\"2026-08-10T02:23:20.946759+00:00\",\"_id\":\"kOANTeTQQSeaY_01vaa7rA\",\"_last_modifier\":\"seafevents\",\"_mtime\":\"2026-08-10T10:23:39+08:00\"}]}]');
